-- Issue #46: 欠落B1試合40件のUpsert用入力固定・バックアップ
-- 作成日: 20260824
-- 実行順: 本SQL → verify（PRE_FIX）→ fix → verify（POST_FIX）
-- 対象: 40 games / 78 game_team_stats / 917 player_game_stats
-- 注意: live DBへの変更はバックアップ表と入力表の作成だけ。既存オブジェクトがあれば停止する。

DO $issue_46_backup$
BEGIN
    IF TO_REGCLASS('public.data_patch_issue46_teams') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_issue46_games') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_issue46_game_team_stats') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_issue46_players') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_issue46_player_game_stats') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_backup_20260824_issue46_teams') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_backup_20260824_issue46_games') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_backup_20260824_issue46_game_team_stats') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_backup_20260824_issue46_players') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_backup_20260824_issue46_player_game_stats') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_backup_20260824_issue46_player_id_map') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_backup_20260824_issue46_team_name_history') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_backup_20260824_issue46_player_name_history') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_backup_20260824_issue46_player_affiliations') IS NOT NULL
       OR TO_REGCLASS('public.data_patch_backup_20260824_issue46_meta') IS NOT NULL THEN
        RAISE EXCEPTION 'Issue #46 input or backup table already exists; inspect before re-running';
    END IF;

    CREATE TABLE public.data_patch_backup_20260824_issue46_meta (
        issue_name TEXT PRIMARY KEY,
        captured_at TIMESTAMPTZ NOT NULL
    );
    VALUES ('Issue #46', CLOCK_TIMESTAMP());

