    schedule_key BIGINT,
    player_id TEXT,
    team_id TEXT,
    jersey_number TEXT,
    is_starter BOOLEAN,
    is_playing BOOLEAN,
    play_time TEXT,
    points INTEGER,
    fgm INTEGER,
    fga INTEGER,
    fg_pct NUMERIC(8, 4),
    fg2m INTEGER,
    fg2a INTEGER,
    fg2_pct NUMERIC(8, 4),
    fg3m INTEGER,
    fg3a INTEGER,
    fg3_pct NUMERIC(8, 4),
    ftm INTEGER,
    fta INTEGER,
    ft_pct NUMERIC(8, 4),
    off_rebounds INTEGER,
    def_rebounds INTEGER,
    total_rebounds INTEGER,
    assists INTEGER,
    turnovers INTEGER,
    steals INTEGER,
    blocks INTEGER,
    blocks_received INTEGER,
    fouls INTEGER,
    fouls_drawn INTEGER,
    fast_break_points INTEGER,
    points_in_paint INTEGER,
    second_chance_points INTEGER,
    efficiency INTEGER,
    plus_minus INTEGER,
