    CREATE TABLE public.data_patch_backup_20260824_issue46_player_id_map AS
        SELECT * FROM public.player_id_map WHERE FALSE;
    SELECT live.*
      FROM public.player_id_map live
     WHERE live.old_player_id IN (
         SELECT DISTINCT player_id FROM public.data_patch_issue46_players
     );

    CREATE TEMP TABLE issue46_backup_player_ids (player_id TEXT PRIMARY KEY) ON COMMIT DROP;
    SELECT DISTINCT COALESCE(m.player_id, i.player_id)
      FROM public.data_patch_issue46_players i
      LEFT JOIN public.player_id_map m ON m.old_player_id = i.player_id;

    CREATE TABLE public.data_patch_backup_20260824_issue46_teams AS
        SELECT * FROM public.teams WHERE FALSE;
    SELECT live.*
      FROM public.teams live
     WHERE live.team_id IN (SELECT team_id FROM public.data_patch_issue46_teams);

    CREATE TABLE public.data_patch_backup_20260824_issue46_games AS
        SELECT * FROM public.games WHERE FALSE;
    SELECT live.*
      FROM public.games live
     WHERE live.schedule_key IN (SELECT schedule_key FROM public.data_patch_issue46_games);

    CREATE TABLE public.data_patch_backup_20260824_issue46_game_team_stats AS
        SELECT * FROM public.game_team_stats WHERE FALSE;
    SELECT live.*
      FROM public.game_team_stats live
     WHERE live.schedule_key IN (SELECT schedule_key FROM public.data_patch_issue46_game_team_stats);

    CREATE TABLE public.data_patch_backup_20260824_issue46_player_game_stats AS
        SELECT * FROM public.player_game_stats WHERE FALSE;
    SELECT live.*
      FROM public.player_game_stats live
     WHERE live.schedule_key IN (SELECT schedule_key FROM public.data_patch_issue46_player_game_stats);

    CREATE TABLE public.data_patch_backup_20260824_issue46_players AS
        SELECT * FROM public.players WHERE FALSE;
    SELECT live.*
      FROM public.players live
     WHERE live.player_id IN (SELECT player_id FROM issue46_backup_player_ids);

    CREATE TABLE public.data_patch_backup_20260824_issue46_player_name_history AS
        SELECT * FROM public.player_name_history WHERE FALSE;
    SELECT live.*
      FROM public.player_name_history live
     WHERE live.player_id IN (SELECT player_id FROM issue46_backup_player_ids);

    CREATE TABLE public.data_patch_backup_20260824_issue46_player_affiliations AS
        SELECT * FROM public.player_affiliations WHERE FALSE;
    SELECT live.*
      FROM public.player_affiliations live
     WHERE live.player_id IN (SELECT player_id FROM issue46_backup_player_ids);

    CREATE TABLE public.data_patch_backup_20260824_issue46_team_name_history AS
        SELECT * FROM public.team_name_history WHERE FALSE;
    SELECT live.*
      FROM public.team_name_history live
     WHERE live.team_id IN (SELECT team_id FROM public.data_patch_issue46_teams);


    IF (SELECT COUNT(*) FROM public.data_patch_issue46_teams) <> 27
       OR (SELECT COUNT(*) FROM public.data_patch_issue46_games) <> 40
       OR (SELECT COUNT(*) FROM public.data_patch_issue46_game_team_stats) <> 78
       OR (SELECT COUNT(*) FROM public.data_patch_issue46_players) <> 687
       OR (SELECT COUNT(*) FROM public.data_patch_issue46_player_game_stats) <> 917 THEN
        RAISE EXCEPTION 'Issue #46 input row-count guard failed';
    END IF;
END;
$issue_46_backup$;

SELECT 'input_teams' AS item, COUNT(*) AS row_count FROM public.data_patch_issue46_teams
UNION ALL SELECT 'input_games', COUNT(*) FROM public.data_patch_issue46_games
UNION ALL SELECT 'input_game_team_stats', COUNT(*) FROM public.data_patch_issue46_game_team_stats
UNION ALL SELECT 'input_players_raw', COUNT(*) FROM public.data_patch_issue46_players
UNION ALL SELECT 'input_player_game_stats', COUNT(*) FROM public.data_patch_issue46_player_game_stats
UNION ALL SELECT 'backup_teams', COUNT(*) FROM public.data_patch_backup_20260824_issue46_teams
UNION ALL SELECT 'backup_games', COUNT(*) FROM public.data_patch_backup_20260824_issue46_games
UNION ALL SELECT 'backup_game_team_stats', COUNT(*) FROM public.data_patch_backup_20260824_issue46_game_team_stats
UNION ALL SELECT 'backup_players', COUNT(*) FROM public.data_patch_backup_20260824_issue46_players
UNION ALL SELECT 'backup_player_game_stats', COUNT(*) FROM public.data_patch_backup_20260824_issue46_player_game_stats
UNION ALL SELECT 'backup_player_id_map', COUNT(*) FROM public.data_patch_backup_20260824_issue46_player_id_map
UNION ALL SELECT 'backup_team_name_history', COUNT(*) FROM public.data_patch_backup_20260824_issue46_team_name_history
UNION ALL SELECT 'backup_player_name_history', COUNT(*) FROM public.data_patch_backup_20260824_issue46_player_name_history
UNION ALL SELECT 'backup_player_affiliations', COUNT(*) FROM public.data_patch_backup_20260824_issue46_player_affiliations;
